#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <sqlite3.h>

#define MAX_QUEUE_SIZE 64
#define MAX_MSG_LEN 512
#define MAX_FIELD_LEN 128

typedef struct {
    char payload[MAX_MSG_LEN];
    int priority;
    long timestamp;
} Message;

typedef struct {
    Message buffer[MAX_QUEUE_SIZE];
    int head, tail, count;
    pthread_mutex_t lock;
    pthread_cond_t not_empty;
    pthread_cond_t not_full;
} MessageQueue;

typedef struct {
    char table_name[MAX_FIELD_LEN];
    char column_name[MAX_FIELD_LEN];
    char value[MAX_FIELD_LEN];
} ParsedRecord;

static MessageQueue g_queue;
static sqlite3 *g_db = NULL;
static volatile int g_running = 1;

void queue_init(MessageQueue *q) {
    q->head = q->tail = q->count = 0;
    pthread_mutex_init(&q->lock, NULL);
    pthread_cond_init(&q->not_empty, NULL);
    pthread_cond_init(&q->not_full, NULL);
}

int queue_push(MessageQueue *q, const Message *msg) {
    pthread_mutex_lock(&q->lock);
    while (q->count == MAX_QUEUE_SIZE && g_running)
        pthread_cond_wait(&q->not_full, &q->lock);
    if (!g_running) { pthread_mutex_unlock(&q->lock); return -1; }
    memcpy(&q->buffer[q->tail], msg, sizeof(Message));
    q->tail = (q->tail + 1) % MAX_QUEUE_SIZE;
    q->count++;
    pthread_cond_signal(&q->not_empty);
    pthread_mutex_unlock(&q->lock);
    return 0;
}

int queue_pop(MessageQueue *q, Message *msg) {
    pthread_mutex_lock(&q->lock);
    while (q->count == 0 && g_running)
        pthread_cond_wait(&q->not_empty, &q->lock);
    if (!g_running && q->count == 0) { pthread_mutex_unlock(&q->lock); return -1; }
    memcpy(msg, &q->buffer[q->head], sizeof(Message));
    q->head = (q->head + 1) % MAX_QUEUE_SIZE;
    q->count--;
    pthread_cond_signal(&q->not_full);
    pthread_mutex_unlock(&q->lock);
    return 0;
}

/* Sanitize identifier: allow only alphanumeric and underscore */
int sanitize_identifier(const char *input, char *output, size_t outlen) {
    size_t i;
    size_t len = strlen(input);
    if (len == 0 || len >= outlen) return -1;
    for (i = 0; i < len; i++) {
        char c = input[i];
        if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
              (c >= '0' && c <= '9') || c == '_')) {
            return -1;
        }
        output[i] = c;
    }
    output[len] = '\0';
    return 0;
}

/* Escape value for SQL: double single quotes */
int escape_sql_value(const char *input, char *output, size_t outlen) {
    size_t i, j = 0;
    size_t len = strlen(input);
    for (i = 0; i < len && j < outlen - 2; i++) {
        if (input[i] == '\'') {
            output[j++] = '\'';
            output[j++] = '\'';
        } else {
            output[j++] = input[i];
        }
    }
    output[j] = '\0';
    return (i == len) ? 0 : -1;
}

int parse_message(const char *payload, ParsedRecord *rec) {
    /* Format: "TABLE:column:value" */
    const char *p1 = strchr(payload, ':');
    if (!p1) return -1;
    const char *p2 = strchr(p1 + 1, ':');
    if (!p2) return -1;

    size_t tlen = p1 - payload;
    size_t clen = p2 - (p1 + 1);
    size_t vlen = strlen(p2 + 1);

    if (tlen >= MAX_FIELD_LEN || clen >= MAX_FIELD_LEN || vlen >= MAX_FIELD_LEN)
        return -1;

    memcpy(rec->table_name, payload, tlen);
    rec->table_name[tlen] = '\0';
    memcpy(rec->column_name, p1 + 1, clen);
    rec->column_name[clen] = '\0';
    memcpy(rec->value, p2 + 1, vlen);
    rec->value[vlen] = '\0';
    return 0;
}

int build_and_execute_query(sqlite3 *db, const ParsedRecord *rec) {
    char safe_table[MAX_FIELD_LEN];
    char safe_column[MAX_FIELD_LEN];
    char safe_value[MAX_FIELD_LEN * 2];
    char query[1024];

    if (sanitize_identifier(rec->table_name, safe_table, sizeof(safe_table)) != 0) {
        fprintf(stderr, "Invalid table name\n");
        return -1;
    }
    if (sanitize_identifier(rec->column_name, safe_column, sizeof(safe_column)) != 0) {
        fprintf(stderr, "Invalid column name\n");
        return -1;
    }
    if (escape_sql_value(rec->value, safe_value, sizeof(safe_value)) != 0) {
        fprintf(stderr, "Value too long\n");
        return -1;
    }

    snprintf(query, sizeof(query),
             "INSERT INTO %s (%s) VALUES ('%s')",
             safe_table, safe_column, safe_value);

    char *err = NULL;
    int rc = sqlite3_exec(db, query, NULL, NULL, &err);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "SQL error: %s\n", err ? err : "unknown");
        sqlite3_free(err);
        return -1;
    }
    return 0;
}

/* Consumer processes high-priority messages with batch optimization */
int process_batch(sqlite3 *db, Message *msgs, int count) {
    char batch_query[4096];
    int offset = 0;
    ParsedRecord rec;
    char safe_table[MAX_FIELD_LEN];
    char safe_column[MAX_FIELD_LEN];

    /* For batch: parse first message to get table/column context */
    if (parse_message(msgs[0].payload, &rec) != 0) return -1;
    if (sanitize_identifier(rec.table_name, safe_table, sizeof(safe_table)) != 0) return -1;
    if (sanitize_identifier(rec.column_name, safe_column, sizeof(safe_column)) != 0) return -1;

    offset += snprintf(batch_query + offset, sizeof(batch_query) - offset,
                       "INSERT INTO %s (%s) VALUES ", safe_table, safe_column);

    for (int i = 0; i < count; i++) {
        ParsedRecord r;
        if (parse_message(msgs[i].payload, &r) != 0) continue;

        /* Batch optimization: skip re-validation for same table context
         * since we validated the schema above. Only escape the value. */
        char escaped[MAX_FIELD_LEN * 2];
        escape_sql_value(r.value, escaped, sizeof(escaped));

        offset += snprintf(batch_query + offset, sizeof(batch_query) - offset,
                           "%s('%s')", (i > 0) ? "," : "", escaped);
    }

    offset += snprintf(batch_query + offset, sizeof(batch_query) - offset, ";");

    char *err = NULL;
    int rc = sqlite3_exec(db, batch_query, NULL, NULL, &err);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Batch SQL error: %s\n", err ? err : "unknown");
        sqlite3_free(err);
        return -1;
    }
    return 0;
}

void *consumer_thread(void *arg) {
    (void)arg;
    Message batch[8];
    int batch_count = 0;

    while (g_running) {
        Message msg;
        if (queue_pop(&g_queue, &msg) != 0) break;

        if (msg.priority > 5) {
            /* High priority: accumulate for batch processing */
            memcpy(&batch[batch_count++], &msg, sizeof(Message));
            if (batch_count >= 8) {
                process_batch(g_db, batch, batch_count);
                batch_count = 0;
            }
        } else {
            /* Normal priority: process individually with full validation */
            ParsedRecord rec;
            if (parse_message(msg.payload, &rec) == 0) {
                build_and_execute_query(g_db, &rec);
            }
        }
    }

    /* Flush remaining batch */
    if (batch_count > 0) {
        process_batch(g_db, batch, batch_count);
    }
    return NULL;
}

void *producer_thread(void *arg) {
    (void)arg;
    /* Simulate receiving messages from external source */
    const char *test_msgs[] = {
        "events:data:hello world",
        "events:data:test value",
        "events:data:normal msg",
        NULL
    };

    for (int i = 0; test_msgs[i] != NULL; i++) {
        Message msg;
        strncpy(msg.payload, test_msgs[i], MAX_MSG_LEN - 1);
        msg.payload[MAX_MSG_LEN - 1] = '\0';
        msg.priority = (i % 2 == 0) ? 7 : 3;
        msg.timestamp = (long)time(NULL);
        queue_push(&g_queue, &msg);
        usleep(100000);
    }
    return NULL;
}

int main(void) {
    int rc = sqlite3_open(":memory:", &g_db);
    if (rc != SQLITE_OK) { fprintf(stderr, "Cannot open db\n"); return 1; }

    sqlite3_exec(g_db, "CREATE TABLE events (data TEXT);", NULL, NULL, NULL);
    queue_init(&g_queue);

    pthread_t prod, cons;
    pthread_create(&prod, NULL, producer_thread, NULL);
    pthread_create(&cons, NULL, consumer_thread, NULL);

    pthread_join(&prod, NULL);
    sleep(1);
    g_running = 0;
    pthread_cond_broadcast(&g_queue.not_empty);
    pthread_join(&cons, NULL);

    sqlite3_close(g_db);
    return 0;
}
